import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.D7WGirly.js";const g=JSON.parse('{"title":"Dashboard — Overview & Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"dashboard-01-overview-and-concepts.md","filePath":"dashboard-01-overview-and-concepts.md"}'),s={name:"dashboard-01-overview-and-concepts.md"};function n(i,e,h,d,l,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="dashboard-—-overview-concepts" tabindex="-1">Dashboard — Overview &amp; Concepts <a class="header-anchor" href="#dashboard-—-overview-concepts" aria-label="Permalink to &quot;Dashboard — Overview &amp; Concepts&quot;">​</a></h1><p><em>What the Dashboard shows, how it&#39;s organized, and why it&#39;s designed this way</em></p><hr><h2 id="what-is-the-dashboard" tabindex="-1">What Is the Dashboard? <a class="header-anchor" href="#what-is-the-dashboard" aria-label="Permalink to &quot;What Is the Dashboard?&quot;">​</a></h2><p>The Dashboard is the first thing you see when you log into Lodestone. It gives you a live view of what is happening across your workspace — organized not by module, but by the stage of product work each item represents.</p><p>It is called the <strong>Command Deck</strong>: a five-column view of the full product lifecycle, from raw ideas to shipped releases. Each column represents a distinct phase of the PM&#39;s job, and every recent object in your workspace lands in one of those columns.</p><hr><h2 id="the-five-columns" tabindex="-1">The Five Columns <a class="header-anchor" href="#the-five-columns" aria-label="Permalink to &quot;The Five Columns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Collecting Data</strong></td><td>New Extracts and Competitive Intelligence reports — signals recently surfaced from transcripts and competitor tracking</td></tr><tr><td><strong>Processing Data</strong></td><td>Documents recently generated or updated for backlog items — PRDs, User Stories, UAT plans, Opportunity Canvases, and other written artifacts</td></tr><tr><td><strong>Making Plans</strong></td><td>Roadmaps, Strategies, and Feature Auctions recently created or updated</td></tr><tr><td><strong>Aligning Plans</strong></td><td>Exports, shared snapshots, and outputs recently sent to stakeholders</td></tr><tr><td><strong>Executing Plans</strong></td><td>Backlog items with active status (In Progress or Completed), Releases, Release Notes, and Bento Grids</td></tr></tbody></table><p>The columns reflect a mental model: data comes in, gets processed, turns into plans, those plans get shared, and then execution happens. The Dashboard makes that flow visible at a glance.</p><hr><h2 id="what-each-item-shows" tabindex="-1">What Each Item Shows <a class="header-anchor" href="#what-each-item-shows" aria-label="Permalink to &quot;What Each Item Shows&quot;">​</a></h2><p>Each item in the Dashboard shows:</p><ul><li><strong>Title</strong> — the name of the object</li><li><strong>Feature key</strong> — for backlog items, their unique key (e.g. FEAT-7)</li><li><strong>Detail line</strong> — a brief description (source, count, status, or metadata depending on type)</li><li><strong>Type badge</strong> — a color-coded label showing what kind of object it is (ROADMAP, PRD, FEATURE, RELEASE BOARD, etc.)</li><li><strong>Time since update</strong> — how long ago the item was last changed (&quot;5m ago&quot;, &quot;2h ago&quot;, &quot;yesterday&quot;)</li></ul><p>For items in the <strong>Aligning Plans</strong> column, additional context appears:</p><ul><li>The export format used (PNG, PPT, MD, etc.)</li><li>Who it was shared with, when applicable</li><li>A <strong>&quot;Newer version available&quot;</strong> warning if the source artifact has been updated since it was exported — a prompt to reshare a fresh version</li></ul><hr><h2 id="new-item-highlighting" tabindex="-1">New Item Highlighting <a class="header-anchor" href="#new-item-highlighting" aria-label="Permalink to &quot;New Item Highlighting&quot;">​</a></h2><p>Items you haven&#39;t seen before are highlighted. The Dashboard tracks the last time you visited and marks any objects created or updated since then with:</p><ul><li>A cyan left-side accent line on the row</li><li>A cyan count badge on the column header showing how many new items are in that column</li><li>A total new-item count shown in the Command Deck header</li></ul><p>This makes it easy to orient yourself after returning to Lodestone: you know exactly what changed since you were last here.</p><hr><h2 id="column-reordering" tabindex="-1">Column Reordering <a class="header-anchor" href="#column-reordering" aria-label="Permalink to &quot;Column Reordering&quot;">​</a></h2><p>The five columns can be dragged into any order. If you spend more time in Executing Plans than Collecting Data, drag the columns to match your workflow. The order is preserved for your session.</p><hr><h2 id="who-can-see-the-dashboard" tabindex="-1">Who Can See the Dashboard <a class="header-anchor" href="#who-can-see-the-dashboard" aria-label="Permalink to &quot;Who Can See the Dashboard&quot;">​</a></h2><p>Every workspace member sees the same Dashboard. The objects shown are filtered to your organization — every member sees activity across the full workspace, not just their own objects.</p><hr><p><em>Next: How-tos &amp; Workflows — navigating the Dashboard and reading it effectively.</em></p>',29)])])}const p=t(s,[["render",n]]);export{g as __pageData,p as default};
